// ============================================================================
// HELPERS
// ============================================================================

function formatDate(dateStr?: string): string {
    if (!dateStr) return '—';
    try {
        return new Intl.DateTimeFormat('en-US', {
            month: 'short',
            day: 'numeric',
            year: 'numeric',
        }).format(new Date(dateStr));
    } catch {
        return '—';
    }
}

function generateId(): string {
    return 'tpl-' + Math.random().toString(36).substring(2, 9);
}

// Compliance validation
function validateCompliance(html: string): { valid: boolean; checks: { label: string; passed: boolean }[] } {
    const checks = [
        { label: 'Unsubscribe link ({{unsubscribe_url}})', passed: html.includes('{{unsubscribe_url}}') },
        { label: 'Business address ({{business_address}})', passed: html.includes('{{business_address}}') },
        { label: 'Contact email ({{contact_email}})', passed: html.includes('{{contact_email}}') },
    ];
    return { valid: checks.every((c) => c.passed), checks };
}

// ============================================================================
// TEMPLATE EDITOR COMPONENT
// ============================================================================

interface EditorProps {
    template: EmailTemplate | null;
    onSave: (template: EmailTemplate) => void;
    onCancel: () => void;
}

const TemplateEditor: React.FC<EditorProps> = ({ template, onSave, onCancel }) => {
    const isNew = !template;
    const [name, setName] = useState(template?.name || '');
    const [subject, setSubject] = useState(template?.subject || '');
    const [type, setType] = useState<TemplateType>(template?.type || 'promotional');
    const [htmlBody, setHtmlBody] = useState(template?.htmlBody || DEFAULT_HTML);
    const [plainText, setPlainText] = useState(template?.plainTextBody || '');
    const [activeTab, setActiveTab] = useState<'html' | 'preview' | 'plain'>('html');
    const [showVars, setShowVars] = useState(false);
    const [feedback, setFeedback] = useState<{ type: 'success' | 'error'; msg: string } | null>(null);

    // Full HTML with compliance footer appended
    const fullHtml = htmlBody + COMPLIANCE_FOOTER;
    const compliance = useMemo(() => validateCompliance(fullHtml), [fullHtml]);

    const canSave = name.trim() && compliance.valid;

    const handleSave = () => {
        if (!canSave) {
            setFeedback({ type: 'error', msg: 'Fix validation errors before saving.' });
            return;
        }
        const now = new Date().toISOString();
        onSave({
            id: template?.id || generateId(),
            name: name.trim(),
            subject: subject.trim(),
            type,
            htmlBody: fullHtml,
            plainTextBody: plainText || undefined,
            createdAt: template?.createdAt || now,
            updatedAt: now,
        });
        setFeedback({ type: 'success', msg: 'Template saved!' });
    };

    const insertVariable = (varName: string) => {
        setHtmlBody((prev) => prev + varName);
        setShowVars(false);
    };

    return (
        <div className="space-y-6">
            {/* Header */}
            <div className="flex items-center gap-3 border-b border-slate-100 pb-5">
                <button onClick={onCancel} className="p-2 hover:bg-slate-100 rounded-xl transition-colors">
                    <ArrowLeft size={20} className="text-slate-600" />
                </button>
                <div className="p-2.5 bg-indigo-600 rounded-xl shadow-lg shadow-indigo-100">
                    <FileText className="w-5 h-5 text-white" />
                </div>
                <div className="flex-1">
                    <h1 className="text-2xl font-black text-slate-900 tracking-tight">
                        {isNew ? 'Create Template' : 'Edit Template'}
                    </h1>
                    <p className="text-[11px] font-bold text-slate-400 uppercase tracking-[0.2em] mt-0.5">
                        {isNew ? 'Build a new email template' : name}
                    </p>
                </div>
                <button
                    onClick={handleSave}
                    disabled={!canSave}
                    className="flex items-center gap-2 px-5 py-2.5 bg-indigo-600 text-white rounded-xl text-sm font-bold shadow-lg shadow-indigo-200 hover:bg-indigo-700 active:scale-95 transition-all disabled:bg-slate-300 disabled:shadow-none"
                >
                    <Save className="w-4 h-4" /> Save Template
                </button>
            </div>

            {feedback && (
                <div className={`p-3 rounded-xl text-sm font-medium flex items-center gap-2 ${feedback.type === 'success' ? 'bg-emerald-50 text-emerald-700' : 'bg-rose-50 text-rose-700'}`}>
                    {feedback.type === 'success' ? <CheckCircle2 className="w-4 h-4" /> : <XCircle className="w-4 h-4" />}
                    {feedback.msg}
                </div>
            )}

            {/* Form fields */}
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                <div className="md:col-span-2">
                    <label className="block text-xs font-bold text-slate-600 uppercase tracking-wider mb-2">Template Name *</label>
                    <input
                        type="text"
                        value={name}
                        onChange={(e) => setName(e.target.value)}
                        placeholder="e.g. Spring Promo Email"
                        className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm focus:border-indigo-500 outline-none transition-all"
                    />
                </div>
                <div>
                    <label className="block text-xs font-bold text-slate-600 uppercase tracking-wider mb-2">Type</label>
                    <select
                        value={type}
                        onChange={(e) => setType(e.target.value as TemplateType)}
                        className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm focus:border-indigo-500 outline-none transition-all font-medium"
                    >
                        {TEMPLATE_TYPES.map((t) => (
                            <option key={t.value} value={t.value}>{t.label}</option>
                        ))}
                    </select>
                </div>
            </div>

            <div>
                <label className="block text-xs font-bold text-slate-600 uppercase tracking-wider mb-2">Email Subject</label>
                <input
                    type="text"
                    value={subject}
                    onChange={(e) => setSubject(e.target.value)}
                    placeholder="e.g. 🌸 Don't miss our spring deals, {{customer_name}}!"
                    className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm focus:border-indigo-500 outline-none transition-all"
                />
            </div>

            {/* HTML Editor / Preview tabs */}
            <div className="bg-white border border-slate-200 rounded-2xl overflow-hidden">
                <div className="flex border-b border-slate-200 bg-slate-50/50">
                    {([
                        { key: 'html', label: 'HTML', icon: Code },
                        { key: 'preview', label: 'Preview', icon: Eye },
                        { key: 'plain', label: 'Plain Text', icon: Type },
                    ] as const).map((tab) => (
                        <button
                            key={tab.key}
                            onClick={() => setActiveTab(tab.key)}
                            className={`flex items-center gap-2 px-5 py-3 text-xs font-bold uppercase tracking-wider transition-all border-b-2
                                ${activeTab === tab.key
                                    ? 'border-indigo-600 text-indigo-700 bg-white'
                                    : 'border-transparent text-slate-400 hover:text-slate-600'}`}
                        >
                            <tab.icon className="w-3.5 h-3.5" /> {tab.label}
                        </button>
                    ))}

                    {/* Variables button */}
                    <div className="ml-auto relative px-3 py-2 flex items-center">
                        <button
                            onClick={() => setShowVars(!showVars)}
                            className="px-3 py-1.5 text-[10px] font-bold text-indigo-600 bg-indigo-50 hover:bg-indigo-100 rounded-lg uppercase tracking-wider transition-all"
                        >
                            + Insert Variable
                        </button>
                        {showVars && (
                            <div className="absolute right-3 top-full mt-1 bg-white border border-slate-200 rounded-xl shadow-xl z-20 py-1 w-52">
                                {AVAILABLE_VARIABLES.map((v) => (
                                    <button
                                        key={v}
                                        onClick={() => insertVariable(v)}
                                        className="w-full text-left px-4 py-2 text-xs font-mono text-slate-700 hover:bg-indigo-50 hover:text-indigo-700 transition-colors"
                                    >
                                        {v}
                                    </button>
                                ))}
                            </div>
                        )}
                    </div>
                </div>

                {/* Tab content */}
                <div className="min-h-[400px]">
                    {activeTab === 'html' && (
                        <div className="relative">
                            <textarea
                                value={htmlBody}
                                onChange={(e) => setHtmlBody(e.target.value)}
                                className="w-full min-h-[400px] p-5 font-mono text-sm text-slate-800 bg-slate-50 border-0 outline-none resize-y leading-relaxed"
                                spellCheck={false}
                                placeholder="Write your HTML email body here..."
                            />
                            {/* Locked compliance footer preview */}
                            <div className="px-5 py-3 bg-emerald-50 border-t border-emerald-200">
                                <div className="flex items-center gap-2 mb-2">
                                    <ShieldCheck className="w-3.5 h-3.5 text-emerald-600" />
                                    <span className="text-[10px] font-black text-emerald-600 uppercase tracking-widest">
                                        Compliance Footer (auto-appended, cannot be removed)
                                    </span>
                                </div>
                                <pre className="text-[11px] text-emerald-800 font-mono whitespace-pre-wrap leading-relaxed opacity-70">
                                    {COMPLIANCE_FOOTER.trim()}
                                </pre>
                            </div>
                        </div>
                    )}

                    {activeTab === 'preview' && (
                        <div className="p-6 bg-slate-100 min-h-[400px]">
                            <div className="max-w-[600px] mx-auto bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
                                {subject && (
                                    <div className="px-5 py-3 bg-slate-50 border-b border-slate-100 flex items-center gap-2">
                                        <span className="text-[10px] font-bold text-slate-400 uppercase">Subject:</span>
                                        <span className="text-sm font-medium text-slate-900">{subject}</span>
                                    </div>
                                )}
                                <div
                                    className="p-6"
                                    dangerouslySetInnerHTML={{ __html: fullHtml }}
                                />
                            </div>
                        </div>
                    )}

                    {activeTab === 'plain' && (
                        <textarea
                            value={plainText}
                            onChange={(e) => setPlainText(e.target.value)}
                            className="w-full min-h-[400px] p-5 font-mono text-sm text-slate-800 bg-white border-0 outline-none resize-y leading-relaxed"
                            placeholder="Optional plain-text version of the email..."
                        />
                    )}
                </div>
            </div>

            {/* Compliance checks */}
            <div className="bg-white border border-slate-200 rounded-2xl overflow-hidden">
                <div className="px-5 py-3 bg-slate-50 border-b border-slate-100 flex items-center gap-2">
                    <ShieldCheck className="w-4 h-4 text-slate-500" />
                    <h3 className="text-xs font-black text-slate-500 uppercase tracking-widest">Compliance Validation</h3>
                </div>
                <div className="divide-y divide-slate-100">
                    {compliance.checks.map((c) => (
                        <div key={c.label} className="flex items-center gap-3 px-5 py-3">
                            {c.passed
                                ? <CheckCircle2 className="w-4 h-4 text-emerald-500 shrink-0" />
                                : <XCircle className="w-4 h-4 text-rose-500 shrink-0" />}
                            <span className={`text-sm ${c.passed ? 'text-slate-600' : 'text-rose-700 font-medium'}`}>{c.label}</span>
                            <span className={`ml-auto text-[10px] font-bold uppercase tracking-wider ${c.passed ? 'text-emerald-600' : 'text-rose-500'}`}>
                                {c.passed ? 'Present' : 'Missing'}
                            </span>
                        </div>
                    ))}
                </div>
                {!compliance.valid && (
                    <div className="px-5 py-3 bg-rose-50 border-t border-rose-200 flex items-center gap-2">
                        <AlertCircle className="w-4 h-4 text-rose-500" />
                        <span className="text-xs font-bold text-rose-700">Template cannot be saved without all compliance fields.</span>
                    </div>
                )}
            </div>

            {/* Info */}
            <div className="p-4 bg-slate-50 border border-slate-200 rounded-xl flex items-start gap-3">
                <Info className="w-4 h-4 text-slate-400 mt-0.5 shrink-0" />
                <p className="text-xs text-slate-500 leading-relaxed">
                    The compliance footer is <strong>automatically appended</strong> to every template and includes unsubscribe link, business address, and contact email.
                    These fields use variables that will be replaced with real values at send time.
                </p>
            </div>
        </div>
    );
};

// ============================================================================
// TEMPLATES LIST PAGE
// ============================================================================

export const TemplatesPage: React.FC = () => {
    const [templates, setTemplates] = useState<EmailTemplate[]>(SAMPLE_TEMPLATES);
    const [view, setView] = useState<'list' | 'editor'>('list');
    const [editingTemplate, setEditingTemplate] = useState<EmailTemplate | null>(null);
    const [searchQuery, setSearchQuery] = useState('');

    const filtered = useMemo(() => {
        if (!searchQuery.trim()) return templates;
        const q = searchQuery.toLowerCase();
        return templates.filter(
            (t) => t.name.toLowerCase().includes(q) || t.type.toLowerCase().includes(q)
        );
    }, [templates, searchQuery]);

    const handleCreate = () => {
        setEditingTemplate(null);
        setView('editor');
    };

    const handleEdit = (tpl: EmailTemplate) => {
        // Strip the compliance footer before editing so user sees only their content
        const bodyWithoutFooter = tpl.htmlBody.replace(COMPLIANCE_FOOTER, '');
        setEditingTemplate({ ...tpl, htmlBody: bodyWithoutFooter });
        setView('editor');
    };

    const handleDuplicate = (tpl: EmailTemplate) => {
        const dup: EmailTemplate = {
            ...tpl,
            id: generateId(),
            name: `${tpl.name} (Copy)`,
            createdAt: new Date().toISOString(),
            updatedAt: new Date().toISOString(),
        };
        setTemplates((prev) => [dup, ...prev]);
    };

    const handleSave = (tpl: EmailTemplate) => {
        setTemplates((prev) => {
            const idx = prev.findIndex((t) => t.id === tpl.id);
            if (idx >= 0) {
                const updated = [...prev];
                updated[idx] = tpl;
                return updated;
            }
            return [tpl, ...prev];
        });
        setView('list');
    };

    const handleCancel = () => {
        setView('list');
        setEditingTemplate(null);
    };

    // ── Editor View ────────────────────────────────────────────────────
    if (view === 'editor') {
        return (
            <div className="max-w-[1000px] mx-auto pb-20 px-2 lg:px-4 pt-2">
                <TemplateEditor template={editingTemplate} onSave={handleSave} onCancel={handleCancel} />
            </div>
        );
    }

    // ── List View ──────────────────────────────────────────────────────
    return (
        <div className="max-w-[1200px] mx-auto space-y-6 pb-20 px-2 lg:px-4">
            {/* Header */}
            <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 border-b border-slate-100 pb-6 pt-2">
                <div className="flex items-center gap-3">
                    <div className="p-2.5 bg-indigo-600 rounded-xl shadow-lg shadow-indigo-100">
                        <FileText className="w-5 h-5 text-white" />
                    </div>
                    <div>
                        <h1 className="text-2xl font-black text-slate-900 tracking-tight">Email Templates</h1>
                        <p className="text-[11px] font-bold text-slate-400 uppercase tracking-[0.2em] mt-0.5">
                            Manage reusable email templates
                        </p>
                    </div>
                </div>
                <button
                    onClick={handleCreate}
                    className="flex items-center gap-2 px-5 py-2.5 bg-indigo-600 text-white rounded-xl text-sm font-bold shadow-lg shadow-indigo-200 hover:bg-indigo-700 hover:scale-[1.02] active:scale-95 transition-all"
                >
                    <Plus className="w-4 h-4" strokeWidth={3} /> New Template
                </button>
            </div>

            {/* ── Section Tabs ─────────────────────────────────────────── */}
            <EmailCampaignTabs />

            {/* Search */}
            <div className="relative">
                <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
                <input
                    type="text"
                    value={searchQuery}
                    onChange={(e) => setSearchQuery(e.target.value)}
                    placeholder="Search templates..."
                    className="w-full pl-11 pr-4 py-2.5 bg-white border border-slate-200 rounded-xl text-sm focus:border-indigo-500 outline-none transition-all"
                />
            </div>

            {/* Template Cards */}
            {filtered.length === 0 ? (
                <div className="flex flex-col items-center justify-center py-20 px-6">
                    <div className="p-5 bg-indigo-50 rounded-2xl mb-5">
                        <FileText className="w-10 h-10 text-indigo-400" />
                    </div>
                    <h2 className="text-lg font-bold text-slate-800">No templates found</h2>
                    <p className="text-sm text-slate-400 mt-1.5 max-w-sm text-center">
                        {searchQuery ? 'Try a different search.' : 'Create your first email template.'}
                    </p>
                </div>
            ) : (
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                    {filtered.map((tpl) => {
                        const typeCfg = TEMPLATE_TYPES.find((t) => t.value === tpl.type) || TEMPLATE_TYPES[TEMPLATE_TYPES.length - 1];
                        return (
                            <div
                                key={tpl.id}
                                className="group bg-white border border-slate-200 rounded-2xl overflow-hidden hover:border-indigo-200 hover:shadow-md hover:shadow-indigo-50 transition-all duration-200"
                            >
                                {/* Preview strip */}
                                <div className="h-32 bg-slate-50 border-b border-slate-100 p-4 overflow-hidden relative">
                                    <div
                                        className="transform scale-[0.35] origin-top-left w-[600px] pointer-events-none"
                                        dangerouslySetInnerHTML={{ __html: tpl.htmlBody }}
                                    />
                                    <div className="absolute inset-0 bg-gradient-to-b from-transparent to-slate-50" />
                                </div>

                                {/* Info */}
                                <div className="p-4">
                                    <div className="flex items-start justify-between mb-2">
                                        <h3 className="text-sm font-bold text-slate-900 line-clamp-1">{tpl.name}</h3>
                                        <span className={`shrink-0 ml-2 text-[10px] font-bold px-2 py-0.5 rounded-full ring-1 ${typeCfg!.color}`}>
                                            {typeCfg!.label}
                                        </span>
                                    </div>
                                    <p className="text-[11px] text-slate-400 truncate mb-3">
                                        {tpl.subject || 'No subject'}
                                    </p>
                                    <div className="flex items-center justify-between">
                                        <span className="text-[10px] font-bold text-slate-400 uppercase tracking-wider">
                                            Updated {formatDate(tpl.updatedAt || tpl.createdAt)}
                                        </span>
                                        <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                                            <button
                                                onClick={() => handleEdit(tpl)}
                                                title="Edit"
                                                className="p-1.5 text-slate-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-lg transition-all"
                                            >
                                                <Pencil className="w-3.5 h-3.5" />
                                            </button>
                                            <button
                                                onClick={() => handleDuplicate(tpl)}
                                                title="Duplicate"
                                                className="p-1.5 text-slate-400 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition-all"
                                            >
                                                <Copy className="w-3.5 h-3.5" />
                                            </button>
                                            <button
                                                onClick={() => handleEdit(tpl)}
                                                title="Preview"
                                                className="p-1.5 text-slate-400 hover:text-emerald-600 hover:bg-emerald-50 rounded-lg transition-all"
                                            >
                                                <Eye className="w-3.5 h-3.5" />
                                            </button>
                                        </div>
                                    </div>
                                </div>
                            </div>
                        );
                    })}
                </div>
            )}
        </div>
    );
};

export default TemplatesPage;
